DO $$ DECLARE n int; BEGIN
  SELECT count(*) INTO n FROM public.icd10_titles;
  IF n < 16905 THEN RAISE EXCEPTION 'seed icd10_titles: % Zeilen, erwartet >= 16905', n; END IF;
END $$;
